      "path": "packages/jev/src/completion-report.ts",
      "content": "/** Current-turn report review, separate from tool-evidence and native Goal supervision. */\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type {} from '@deepseek-ai/dsh-tool-todo'\nimport { JevError } from './index.ts'\nimport type { JevRequest, JevResponse, Json } from './types.ts'\n\nconst assessments = {\n  complete: 'The supplied report shows that the current-turn requirements are satisfied, with no obvious omission or contradiction. This is not independent verification of code or artifacts.',\n  omission: 'A current-turn requirement is unreported, unfinished, or has an unmet user-specified condition. Do not invent verification or delivery requirements.',\n  contradiction: 'Todo content or status and the final report disagree. This identifies a report inconsistency, not a verified code defect.',\n  'needs-user': 'Completion requires an unresolved user choice or authorization. An already-authorized report correction does not require a new decision.',\n  unknown: 'The supplied material is insufficient to judge reliably. This does not mean task success, task failure, or a technical request error.',\n}\n\n/** The one selected issue; quotation text comes only from this request's generated options. */\nexport interface CompletionVerdict { value: string; reason: string; issueKey: string }\n\n/** Read only native records from the latest turn, including a cleared Todo list.\n * @param agent - live ordinary root Agent.\n * @param requestId - original direct-user identity captured at turn admission.\n * @param supplements - already used or durably reserved supplemental rounds.\n * @param maximum - current profile's supplemental round limit.\n * @param budget - character limit saved with the actual input.\n * @returns no input for a turn that has never written Todo, otherwise complete report material.\n */\nexport function completionReport(agent: Agent, requestId: string, supplements: number, maximum: number, budget: number): JevRequest | undefined {\n  const events = agent.session.snapshotEvents()\n  const start = events.findLastIndex(event => event.type === 'turn/start')\n  const turn = events.slice(Math.max(0, start))\n  const todo = turn.findLast(event => event.type === 'todo/write')\n  if (todo?.type !== 'todo/write') return undefined\n  const requirements = turn.flatMap(event => event.type === 'user/message' && event.data.source.kind === 'user'\n    ? [{ id: event.data.id, content: event.data.content }] : [])\n  const originalAvailable = start >= 0 && requirements.some(message => message.id === requestId)\n  const final = turn.findLast(event => event.type === 'assistant/message')\n  const finalText = final?.type === 'assistant/message'\n    ? final.data.message.content.filter(block => block.type === 'text').map(block => block.text).join('\\n') : ''\n  const options = [\n    ...requirements.map((message, index) => ({ id: `requirement-${index + 1}`, description: JSON.stringify(message.content) })),\n    ...todo.data.todos.map((item, index) => ({ id: `todo-${index + 1}`, description: `[${item.status}] ${item.content}` })),\n    { id: 'final-answer', description: finalText || '最终正文为空 / Empty final answer' },\n    { id: 'overall', description: '整体材料 / The complete supplied material' },\n    { id: 'none', description: '未发现问题 / No issue identified (complete only)' },\n  ]\n  const state: Json = {\n    mode: 'completion', reviewPoint: String(final?.seq ?? todo.seq), evidenceScope: 'current turn requirements, latest Todo and latest final answer only',\n    requirements: requirements.map(message => ({ id: message.id, content: JSON.parse(JSON.stringify(message.content)) as Json })),\n    todos: todo.data.todos.map(item => ({ content: item.content, status: item.status })), finalAnswer: finalText,\n    originalRequirementsAvailable: originalAvailable, supplementsUsed: supplements, maxSupplementRounds: maximum, evidenceCharacterBudget: budget,\n    rules: 'Review the supplied report only. The original requirements and subsequent adjustments are in chronological order; later explicit adjustments apply. Todo may contain historical work, but it does not replace the current-turn user requirements. Do not infer an earlier task from a new request saying continue. Empty Todo and empty final text are valid material. Select only the single most important issue; this is not an exhaustive review. Do not infer actual tool execution or artifact correctness from self-reported completion. Tests need to pass only if the user required that condition: running and truthfully reporting failed tests can satisfy a run-and-report request; a fix-and-pass request remains unmet while those tests fail. Todo pending status alone does not establish failure. Supplements stay within existing authorization, including read-only restrictions, and must not redo unrelated completed work, fabricate results, or force completed status. Unknown calls for truthful supporting information or an explanation of what remains unverified. Plugin notices are neither new user requirements nor new authorization.',\n  }\n  return { state, questions: [\n    { id: 'assessment', kind: 'choice', prompt: 'Assess the current-turn report using the supplied rules.', options: Object.entries(assessments).map(([id, description]) => ({ id, description })) },\n    { id: 'focus', kind: 'choice', prompt: 'Choose the most important existing requirement, Todo entry, or final answer. Use overall for material-wide uncertainty; none is permitted only for complete.', options },\n  ] }\n}\n\n/** Refuse incomplete originals or oversized complete material without transport or truncation.\n * @param request - exact saved input and its reference options.\n * @param budget - live character limit for serialized material and both questions.\n */\nexport function completionPreflight(request: JevRequest, budget: number): void {\n  if (typeof request.state !== 'object' || request.state === null || Array.isArray(request.state) || !('originalRequirementsAvailable' in request.state) || request.state.originalRequirementsAvailable !== true) {\n    throw new JevError('COMPLETION_INPUT_MISSING', '本轮原始要求缺失，本次完成核查未完成 / Original current-turn requirements are unavailable; completion review did not finish')\n  }\n  if (JSON.stringify(request).length > budget) {\n    throw new JevError('COMPLETION_BUDGET', '核查材料超出预算，本次完成核查未完成 / Review material exceeds the character budget; completion review did not finish')\n  }\n}\n\n/** Validate both bounded answers; valid unknown is a business conclusion.\n * @param response - normalized provider answer.\n * @param request - actual input defining all permitted references.\n * @returns the assessment and its exact selected quotation, or no verdict for invalid answers.\n */\nexport function completionVerdict(response: JevResponse, request: JevRequest): CompletionVerdict | undefined {\n  const assessment = response.answers.find(answer => answer.id === 'assessment')\n  const focus = response.answers.find(answer => answer.id === 'focus')\n  if (response.answers.length !== 2 || assessment?.kind !== 'choice' || focus?.kind !== 'choice' || !Object.hasOwn(assessments, assessment.optionId)) return undefined\n  const question = request.questions.find(question => question.id === 'focus')\n  const selected = question?.kind === 'choice' ? question.options.find(option => option.id === focus.optionId) : undefined\n  if (selected === undefined || (selected.id === 'none' && assessment.optionId !== 'complete')) return undefined\n  const labels: Record<string, string> = {\n    complete: '报告核查完成 / Report review complete', omission: '发现遗漏或未满足条件 / Omission or unmet condition',\n    contradiction: '报告前后矛盾，请核对并更正 / Check and correct inconsistent reporting',\n    unknown: '材料不足，请补充真实依据或说明 / Add truthful supporting information or explain uncertainty',\n    'needs-user': '需要用户决定 / A user decision is needed',\n  }\n  return { value: assessment.optionId, reason: `${labels[assessment.optionId]}\\n材料引用 / Material reference ${selected.id}: ${selected.description}`, issueKey: selected.id }\n}\n"
    },
    {
      "path": "packages/jev/src/supervision.ts",
      "content": "/** Execution supervision over the public Agent, tool and native goal hooks. */\nimport type { Context, Volatile } from '@deepseek-ai/cordis'\nimport s from '@deepseek-ai/schemastery'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { GoalView } from '@deepseek-ai/dsh-goal'\nimport { createUserMessage, type UserMessage } from '@deepseek-ai/dsh-llm'\nimport type {} from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-tools'\nimport type {} from '@deepseek-ai/dsh-system-prompt'\nimport { completionReport, completionVerdict, completionPreflight } from './completion-report.ts'\nimport type { JevJudgeOptions, JevJudgeResult } from './index.ts'\nimport type { JevRequest, JevResponse, Json } from './types.ts'\nimport type { SupervisionConfigValues } from './supervision-types.ts'\n\n/** Positive profile counts; feature switches live in the common Jev service. */\nexport interface Config { driftInterval: Volatile<number>; noProgressRounds: Volatile<number>; evidenceChars: Volatile<number>; maxSupplementRounds: Volatile<number> }\nexport const Config: s<SupervisionConfigValues, Config> = s.object({\n  maxSupplementRounds: s.number().step(1).min(1).max(Number.MAX_SAFE_INTEGER).default(3).volatile(),\n  driftInterval: s.number().step(1).min(1).max(Number.MAX_SAFE_INTEGER).default(6).volatile(),\n  evidenceChars: s.number().step(1).min(1).max(1_000_000).default(24_000).volatile(),\n  noProgressRounds: s.number().step(1).min(1).max(Number.MAX_SAFE_INTEGER).default(3).volatile(),\n})\n\ndeclare module '@deepseek-ai/dsh-llm' {\n  interface MessageSourceMap {\n    'jev-supervision': { kind: 'jev-supervision'; form: 'notice'; summary: string; requestId: string; action: string; operationId: string }\n  }\n}\n\ntype Check = 'drift-monitoring' | 'completion-check' | 'goal-supervision'\ninterface Verdict { value: string; reason: string; issueKey: string }\ninterface State {\n  steps: number\n  enabled: boolean\n  active: boolean\n  turn: number\n  requestId: string\n  completionRequestId: string\n  completionChecking: boolean\n  signal?: AbortSignal\n  reminderScope: string\n  ownsGoalTurn: boolean\n  reminded: Set<string>\n  pending: { outcome: Extract<JevJudgeResult, { kind: 'ok' }>; verdict: Verdict; version: string }[]\n  stalled: number\n  goalRevision: string\n  lastRound: number\n}\n\nconst choices = {\n  drift: ['on-track', 'drift', 'unknown'],\n  completion: ['complete', 'omission', 'needs-user', 'unknown'],\n  progress: ['progress', 'no-progress', 'needs-user', 'unknown'],\n} as const\n\nfunction verdict(response: JevResponse, request: JevRequest): Verdict | undefined {\n  const assessment = response.answers.find(answer => answer.id === 'assessment')\n  const evidence = response.answers.find(answer => answer.id === 'evidence')\n  if (response.answers.length !== 2 || assessment?.kind !== 'choice' || evidence?.kind !== 'choice') return undefined\n  const question = request.questions.find(question => question.id === 'evidence')\n  if (question?.kind !== 'choice') return undefined\n  const selected = question.options.find(option => option.id === evidence.optionId)\n  if (selected === undefined || selected.id === 'insufficient-evidence') return undefined\n  const state = request.state\n  if (typeof state !== 'object' || state === null || Array.isArray(state) || !('completeEvidence' in state) || state.completeEvidence !== true) return undefined\n  const labels: Record<string, string> = {\n    'on-track': '当前工作与要求一致 / Work follows the requirement',\n    drift: '当前工作偏离所选要求；请回到该要求 / Return to the selected requirement',\n    complete: '已有证据支持完成 / Recorded evidence supports completion',\n    omission: '所选要求仍有缺项或最终事实与记录矛盾；请如实更正报告，其他补做限原授权，不擅自回滚、删除或修改文件 / Correct final factual claims contradicted by recorded evidence; address other omissions only within the original authorization, without unauthorized rollback, deletion, or file changes',\n    'needs-user': '需要用户决定 / A user decision is needed',\n    progress: '本轮增加有效调查或推进证据 / This round added useful evidence or progress',\n    'no-progress': '本轮没有新增有效证据或推进 / This round added no useful evidence or progress',\n    unknown: '证据不足 / Insufficient evidence',\n  }\n  return { value: assessment.optionId, reason: `${labels[assessment.optionId] ?? assessment.optionId}\\n记录引用 / Recorded reference ${selected.id}: ${String(selected.description)}`, issueKey: selected.id }\n}\n\nfunction lastUser(agent: Agent): string {\n  return agent.session.deriveMessages().findLast(message => message.role === 'user' && message.source.kind === 'user')?.id ?? ''\n}\n\nfunction goalIdentity(goal: GoalView | undefined): string {\n  return goal === undefined ? '' : `${goal.id}:${goal.revision}:${goal.phase}`\n}\n\nfunction version(ctx: Context, agent: Agent): string {\n  return JSON.stringify([lastUser(agent), goalIdentity(ctx.goals.get(agent)),\n    [...agent.inbox.nextStep, ...agent.inbox.nextTurn].filter(message => message.source.kind === 'user').map(message => message.id)])\n}\n\n/** Only recorded visible evidence is sent; reasoning blocks and new filesystem reads are excluded. */\nfunction evidence(ctx: Context, agent: Agent, mode: keyof typeof choices, budget: number, requestId: string): JevRequest {\n  const history = agent.session.deriveMessages()\n  const goal = ctx.goals.get(agent)\n  let start = Math.max(0, history.findIndex(message => message.id === requestId))\n  if (goal?.phase === 'active') {\n    const rounds = history.flatMap((message, index) => message.role === 'user' && message.source.kind === 'goal'\n      && message.source.goalId === goal.id && message.source.revision === goal.revision && message.source.round > 0 ? [index] : [])\n    start = mode === 'progress' ? rounds.at(-2) ?? rounds.at(-1) ?? start : rounds[0] ?? start\n  }\n  const all = history.slice(start).map(message => ({\n    id: message.id, role: message.role,\n    ...message.role === 'user' ? { source: message.source.kind } : {},\n    content: message.content.filter(block => block.type !== 'reasoning'),\n  }))\n  const messages: typeof all = []\n  const goalSize = goal?.phase === 'active' ? JSON.stringify(goal).length : 0\n  const omittedGoal = goalSize > budget\n  let remaining = Math.max(0, budget - goalSize)\n  let omitted = 0\n  for (const message of all.toReversed()) {\n    const size = JSON.stringify(message).length\n    if (size > remaining) { omitted++; continue }\n    messages.unshift(message)\n    remaining -= size\n  }\n  const candidates = messages.filter(message => message.role === 'user' && (message.source === 'user' || message.source === 'goal'))\n  const selected = candidates.length === 0 ? messages : candidates\n  const options: { id: string; description: string }[] = selected.map(message => ({ id: message.id,\n    description: JSON.stringify(message.content).slice(0, 800) + (JSON.stringify(message.content).length > 800 ? ' [excerpt; full record above]' : '') }))\n  if (goal?.phase === 'active') options.unshift({ id: goalIdentity(goal), description: omittedGoal ? 'Goal objective exceeds evidence budget; choose unknown.' : goal.objective })\n  if (options.length === 0) options.push({ id: 'no-evidence', description: 'No evidence fits the configured budget; choose unknown.' })\n  if (options.length < 2) options.push({ id: 'insufficient-evidence', description: 'No supplied reference supports an assessment; choose unknown.' })\n  const completionRules = 'Check the submitted answer and claimed deliverables, verification results, and side effects against the actual recorded tool results and applicable user requirements. A final factual claim contradicted by recorded evidence is an omission requiring correction, even if the requested investigation is otherwise finished; it cannot be complete. A supplement may correct the report or complete only work already allowed by the user. Read-only or no-repair instructions remain binding: do not require deleting artifacts, repairing files, or other unauthorized work. A reminder is not itself proof of a violation or a mandatory pause; needs-user requires an actual unresolved user decision, not merely a reminder or a correctable factual error.'\n  const state = JSON.parse(JSON.stringify({\n    mode, goal: omittedGoal ? { id: goal?.id ?? '', objectiveOmitted: true } : goal ?? null, messages, completeEvidence: !omittedGoal && omitted === 0 && messages.length > 0, omittedMessages: omitted, excludedEarlierMessages: start, evidenceScope: goal?.phase === 'active' ? mode === 'progress' ? 'current and previous goal round with current goal' : 'current goal revision rounds' : 'original user request and its subsequent work', evidenceCharacterBudget: budget,\n    rules: 'Use only recorded evidence. Assistant completion claims and successful tool dispatch are not verification. A test started without a result is not passed. A pass before later edits is stale for those edits. Explicitly required verification missing is an omission; insufficient information or omitted evidence is unknown. Necessary investigation and eliminating a relevant hypothesis are progress. Ignoring a reminder alone is not no-progress. In progress mode compare evidence added by the latest goal round to prior rounds. Select the requirement or recorded message supporting your assessment in the evidence question. Do not invent requirements or execute tools.'\n      + (mode === 'completion' ? ' ' + completionRules : ''),\n  })) as Json\n  const completionDescriptions = {\n    complete: 'The requested work and final factual claims are supported by recorded evidence, with no outstanding required work, verification, or factual correction.',\n    omission: 'Recorded evidence identifies unfinished required work, missing required verification, or a contradicted final factual claim that can be corrected within the existing user authorization.',\n    'needs-user': 'An unresolved decision or authorization from the user is necessary to finish; a report correction or other already-authorized work cannot resolve it.',\n    unknown: 'The recorded evidence is insufficient or omitted, so completion cannot be determined; do not infer success or invent missing work.',\n  }\n  return { state, questions: [\n    { id: 'assessment', kind: 'choice', prompt: 'Assess ' + mode + ' from the existing evidence only.' + (mode === 'completion' ? ' ' + completionRules : ''), options: mode === 'completion'\n      ? choices.completion.map(id => ({ id, description: completionDescriptions[id] }))\n      : choices[mode].map(id => ({ id, description: id })) },\n    { id: 'evidence', kind: 'choice', prompt: 'Which recorded requirement or message most directly supports the assessment?', options },\n  ] }\n}\n\n/** Install three independently enabled consumers; native goals retain exclusive continuation ownership. */\nexport function apply(ctx: Context, config: Config): void {\n  const states = new WeakMap<Agent, State>()\n  for (const feature of [\n    { id: 'drift-monitoring', name: '跑偏提醒 / Drift reminders', description: '后台检查已完成步骤；只提醒一次，不打断执行 / Background, non-blocking reminders' },\n    { id: 'completion-check', name: '完成核查 / Completion check', description: '回答展示后核查，按本轮报告核查，有限次补充 / Check current-turn reports with limited supplements' },\n    { id: 'goal-supervision', name: '目标增强 / Goal supervision', description: '核查模型完成申请；连续无进展暂停原生目标 / Guard completion and pause stalled native goals' },\n  ]) ctx.effect(() => ctx.jev.registerFeature(feature))\n  ctx.effect(() => ctx.systemPrompt.section({\n    name: 'jev-completion-todo', order: 650,\n    text: ({ agent }) => agent !== undefined && ctx.agents.get(agent.id) === agent && ctx.agents.roots().includes(agent)\n      && ctx.goals.get(agent)?.phase !== 'active' && !states.get(agent)?.ownsGoalTurn && ctx.jev.isFeatureEnabled('completion-check')\n      ? 'When updating an existing Todo, briefly include actual actions, artifact paths, or executed commands and observed results in its content. Keep failures, unfinished work, and unverified results truthful. Do not create a Todo for a simple task solely for this check; no extra fields, evidence report, or separate preparation round is required.' : '',\n  }))\n  ctx.effect(() => ctx.settings.configure({ auto: false }, ctx.fiber), 'jev-supervision.settings')\n  const tasks = new Set<Promise<void>>()\n  const assessments = new Map<string, Verdict>()\n  const lifetime = new AbortController()\n  ctx.effect(() => async () => { lifetime.abort(); await Promise.allSettled([...tasks]) })\n\n  const live = (agent: Agent | undefined): agent is Agent => agent !== undefined && ctx.agents.get(agent.id) === agent && ctx.agents.roots().includes(agent)\n  const enabled = (feature: Check) => ctx.jev.isFeatureEnabled(feature)\n  const stateFor = (agent: Agent): State => {\n    let state = states.get(agent)\n    if (state === undefined) {\n      state = { steps: 0, enabled: false, active: false, turn: -1, requestId: '', completionRequestId: '', completionChecking: false, reminderScope: '', ownsGoalTurn: false, reminded: new Set(), pending: [], stalled: 0, goalRevision: '', lastRound: -1 }\n      states.set(agent, state)\n    }\n    return state\n  }\n  const receipt = (id: string, action: string, status: 'observed' | 'executed' | 'not-adopted', reason?: string) =>\n    ctx.jev.writeReceipt(id, { id: action, status, at: new Date().toISOString(), ...reason === undefined ? {} : { reason } })\n  const notice = (state: State, operationId: string, action: string, text: string): UserMessage => createUserMessage({\n    source: { kind: 'jev-supervision', form: 'notice', summary: text, requestId: action === 'supplement' || action.startsWith('completion-') || action === 'supplement-unconfirmed' ? state.completionRequestId : state.requestId, action, operationId },\n    content: [{ type: 'text', text }],\n  })\n  const pause = (agent: Agent) => {\n    const goal = ctx.goals.get(agent)\n    if (goal?.phase === 'active') ctx.agents.withInitiator(agent, () => ctx.goals.pause(agent, { id: goal.id, revision: goal.revision }))\n  }\n  const current = (agent: Agent, state: State, identity: string) =>\n    live(agent) && state.active && !state.signal?.aborted && version(ctx, agent) === identity\n\n  async function judge(agent: Agent, state: State, mode: 'completion' | 'progress', signal: AbortSignal, feature?: Check): Promise<JevJudgeResult> {\n    let identity = ''\n    let goalAtAttempt = ''\n    let request: JevRequest\n    const outcome = await ctx.jev.judge({\n      featureId: feature ?? (mode === 'completion' && ctx.goals.get(agent)?.phase !== 'active' ? 'completion-check' : 'goal-supervision'),\n      agent, signal, link: { sessionId: agent.session.id, inputVersion: state.requestId },\n      refresh: () => { identity = version(ctx, agent); goalAtAttempt = goalIdentity(ctx.goals.get(agent)); request = evidence(ctx, agent, mode, config.evidenceChars.get(), state.requestId); return request },\n      interpret: response => {\n        const result = verdict(response, request)\n        return result !== undefined && result.value !== 'unknown' ? { usable: true } : { usable: false, reason: 'Jev 无法判定 / Evidence is insufficient for this check' }\n      },\n      canAdopt: () => current(agent, state, identity) || 'Requirements, goal, or execution changed',\n    })\n    if (outcome.kind === 'ok') assessments.set(outcome.operationId, verdict(outcome.response, request!)!)\n    if (outcome.kind === 'cancelled' && goalIdentity(ctx.goals.get(agent)) === goalAtAttempt) pause(agent)\n    return outcome\n  }\n\n  async function supplementUsage(agent: Agent, requestId: string): Promise<{ used: number; processedStops: Set<string>; unconfirmedOperationId?: string }> {\n    const delivered = new Set(agent.session.snapshotEvents().flatMap(event => event.type === 'user/message'\n      && event.data.source.kind === 'jev-supervision' && event.data.source.requestId === requestId && event.data.source.action === 'supplement'\n      ? [event.data.source.operationId] : []))\n    const used = new Set(delivered)\n    const processedStops = new Set<string>()\n    let unconfirmedOperationId: string | undefined\n    let cursor: string | undefined\n    do {\n      const page = await ctx.jev.listRecords({ featureId: 'completion-check', sessionId: agent.session.id, limit: 100, ...cursor === undefined ? {} : { cursor } })\n      for (const item of page.items) {\n        const record = await ctx.jev.getRecord(item.id)\n        if (record?.link.inputVersion !== requestId) continue\n        if (record.link.stepId !== undefined && (record.status === 'cancelled' || record.status === 'succeeded')\n          && !record.receipts.some(item => item.status === 'not-adopted')) processedStops.add(record.link.stepId)\n        if (!record.receipts.some(item => item.id === 'supplement-reserved')) continue\n        if (record.receipts.some(item => item.id === 'supplement-stale')) continue\n        used.add(record.id)\n        if (!delivered.has(record.id) && !record.receipts.some(item => item.id === 'supplement-queued')) unconfirmedOperationId = record.id\n      }\n      cursor = page.nextCursor\n    } while (cursor !== undefined)\n    return { used: used.size, processedStops, ...unconfirmedOperationId === undefined ? {} : { unconfirmedOperationId } }\n  }\n\n  const completionIdentity = (agent: Agent) => JSON.stringify([version(ctx, agent),\n    [...agent.inbox.nextStep, ...agent.inbox.nextTurn].filter(message => message.source.kind === 'user')])\n  const completionCurrent = (agent: Agent, state: State, identity: string) =>\n    live(agent) && state.active && !state.signal?.aborted && completionIdentity(agent) === identity\n      && agent.inbox.nextStep.length === 0 && !agent.inbox.nextTurn.some(message => message.source.kind === 'user')\n\n  async function checkReport(agent: Agent, state: State, signal: AbortSignal): Promise<void> {\n    const initial = completionReport(agent, state.completionRequestId, 0, config.maxSupplementRounds.get(), config.evidenceChars.get())\n    if (initial === undefined) return\n    const reviewPoint = typeof initial.state === 'object' && initial.state !== null && 'reviewPoint' in initial.state ? String(initial.state.reviewPoint) : ''\n    const usage = await supplementUsage(agent, state.completionRequestId)\n    if (usage.unconfirmedOperationId !== undefined) {\n      if (agent.session.snapshotEvents().some(event => event.type === 'user/message' && event.data.source.kind === 'jev-supervision'\n        && event.data.source.operationId === usage.unconfirmedOperationId && event.data.source.action === 'supplement-unconfirmed')) return\n      await receipt(usage.unconfirmedOperationId, 'supplement-unconfirmed', 'observed', 'Previous supplement has an unknown action status; do not repeat it')\n      agent.session.append('user/message', notice(state, usage.unconfirmedOperationId, 'supplement-unconfirmed', '上次补充状态未确认，本次完成核查未完成 / Previous supplement remains unconfirmed; completion review did not finish'), { surfaceOp: 'append' })\n      return\n    }\n    if (usage.processedStops.has(reviewPoint)) return\n    let identity = ''\n    let request: JevRequest\n    const result = await ctx.jev.judge({\n      featureId: 'completion-check', agent, signal, link: { sessionId: agent.session.id, inputVersion: state.completionRequestId, stepId: reviewPoint },\n      refresh: () => {\n        identity = completionIdentity(agent)\n        const input = completionReport(agent, state.completionRequestId, usage.used, config.maxSupplementRounds.get(), config.evidenceChars.get())\n        if (input === undefined) throw new Error('Current turn changed during completion review')\n        request = input\n        return request\n      },\n      preflight: input => completionPreflight(input, config.evidenceChars.get()),\n      failureDetail: failure => `本次完成核查未完成 / Completion review did not finish: ${failure.message}. 请调整配置后重试，或取消本次核查 / Retry with current input and settings, or cancel this review.`,\n      interpret: response =